"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25584"],{88507(e){e.exports=JSON.parse('{"id":"F509","slug":"cash-flow-statement-link","name":"Linking the Three Statements: Cash Flow and Balance Check","subject":"Accounting Mastery & Financial Modeling","section":"Financial statement mechanics","topic":"Financial statement mechanics","level":"Intermediate","aliases":["indirect method","cash flow statement","balance sheet check","three statement model"],"formula":{"latex":"\\\\Delta Cash=CFO+CFI+CFF,\\\\quad CFO=NI+D\\\\&A-\\\\Delta NWC","also":[],"text":"Cash flow from operations = Net income + Depreciation - Increase in working capital; Cash flow from investing = -Capex; Cash flow from financing = Debt issued - Debt repaid - Dividends + Shares issued; Ending cash = Opening cash + total cash flow"},"symbols":[{"symbol":"NI","meaning":"Net income from the income statement","unit":"money"},{"symbol":"D&A","meaning":"Depreciation and amortization, a non-cash expense added back","unit":"money"},{"symbol":"Delta NWC","meaning":"Increase in net working capital from the balance sheet, which uses cash","unit":"money"},{"symbol":"CFO, CFI, CFF","meaning":"Cash flows from operating, investing and financing activities","unit":"money"}],"when_to_use":"Use it to see how the three statements connect. Net income flows into the cash flow statement and retained earnings. Capex and depreciation move fixed assets. Debt and dividends change liabilities and equity. Ending cash goes back to the balance sheet, and the balance sheet must still balance, which is the check at the bottom.","worked_example":{"problem":"A company has net income of 90, depreciation of 90, an increase in working capital of 20 and capex of 110. It issues 50 of debt, repays 20 and pays dividends of 30. Opening cash is 100.","inputs":{"ni":90,"da":90,"dnwc":20,"capex":110,"iss":50,"rep":20,"div":30,"cash0":100},"steps":[{"label":"CFO = NI + D&A - increase in NWC","working":"90+90-20","value":"160.00"},{"label":"CFI = -capex","working":"-110","value":"-110.00"},{"label":"CFF = debt issued - repaid - dividends","working":"50-20-30","value":"0.00"},{"label":"Net change in cash","working":"160+-110+0","value":"50.00"},{"label":"Ending cash","working":"100+50","value":"150.00"},{"label":"Change in assets = cash change + capex - depreciation + increase in NWC","working":"50+110-90+20","value":"90.00"},{"label":"Change in liabilities and equity = debt change + NI - dividends","working":"50-20+90-30","value":"90.00"},{"label":"Difference (must be zero)","working":"90-90","value":"0.00"}],"answer":"Operations bring in 160.00, investing uses -110.00 and financing gives 0.00. Cash rises by 50.00 to 150.00. Balance check: assets rose by 90.00 and liabilities plus equity rose by 90.00, a difference of 0.00, so the model balances."},"calculator":{"available":true,"inputs":[{"id":"ni","label":"Net income","unit":"money","type":"number","default":90,"hint":""},{"id":"da","label":"Depreciation and amortization","unit":"money","type":"number","default":90,"hint":""},{"id":"dnwc","label":"Increase in working capital","unit":"money","type":"number","default":20,"hint":""},{"id":"capex","label":"Capital expenditure","unit":"money","type":"number","default":110,"hint":""},{"id":"iss","label":"Debt issued","unit":"money","type":"number","default":50,"hint":""},{"id":"rep","label":"Debt repaid","unit":"money","type":"number","default":20,"hint":""},{"id":"div","label":"Dividends paid","unit":"money","type":"number","default":30,"hint":""},{"id":"cash0","label":"Opening cash","unit":"money","type":"number","default":100,"hint":""}],"checks":[],"steps":[{"id":"cfo","label":"CFO = NI + D&A - increase in NWC","expr":"ni+da-dnwc","format":"money"},{"id":"cfi","label":"CFI = -capex","expr":"-capex","format":"money"},{"id":"cff","label":"CFF = debt issued - repaid - dividends","expr":"iss-rep-div","format":"money"},{"id":"net","label":"Net change in cash","expr":"cfo+cfi+cff","format":"money"},{"id":"cash1","label":"Ending cash","expr":"cash0+net","format":"money"},{"id":"dassets","label":"Change in assets = cash change + capex - depreciation + increase in NWC","expr":"net+capex-da+dnwc","format":"money"},{"id":"dlne","label":"Change in liabilities and equity = debt change + NI - dividends","expr":"iss-rep+ni-div","format":"money"},{"id":"diff","label":"Difference (must be zero)","expr":"dassets-dlne","format":"money"}],"results":["net","cash1","diff"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cfo":160,"cfi":-110,"cff":0,"net":50,"cash1":150,"dassets":90,"dlne":90,"diff":0}},"finder":{"finds":"Ending cash and a check that the balance sheet balances","needs":"Net income, depreciation, working capital, capex, financing flows, opening cash"},"related":[{"slug":"net-change-in-cash","name":"Net Change in Cash"},{"slug":"retained-earnings","name":"Retained Earnings Roll-Forward"},{"slug":"accounting-equation","name":"The Accounting Equation"},{"slug":"ppe-rollforward","name":"PP&E Roll-Forward"}],"related_ids":["F068","F069","F063","F510"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi mathvariant=\\"normal\\">\u0394</mi><mi>C</mi><mi>a</mi><mi>s</mi><mi>h</mi><mo>=</mo><mi>C</mi><mi>F</mi><mi>O</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>I</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>F</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>C</mi><mi>F</mi><mi>O</mi><mo>=</mo><mi>N</mi><mi>I</mi><mo>+</mo><mi>D</mi><mi mathvariant=\\"normal\\">&amp;</mi><mi>A</mi><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>N</mi><mi>W</mi><mi>C</mi></mrow><annotation encoding=\\"application/x-tex\\">\\\\Delta Cash=CFO+CFI+CFF,\\\\quad CFO=NI+D\\\\&amp;A-\\\\Delta NWC</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi mathvariant=\\"normal\\">\u0394</mi><mi>C</mi><mi>a</mi><mi>s</mi><mi>h</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\Delta Cash</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>C</mi><mi>F</mi><mi>O</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>I</mi><mo>+</mo><mi>C</mi><mi>F</mi><mi>F</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =CFO+CFI+CFF</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>C</mi><mi>F</mi><mi>O</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle CFO</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mi>N</mi><mi>I</mi><mo>+</mo><mi>D</mi><mi mathvariant=\\"normal\\">&amp;</mi><mi>A</mi><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>N</mi><mi>W</mi><mi>C</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =NI+D\\\\&amp;A-\\\\Delta NWC</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"supply-demand-equilibrium","name":"Linear Supply and Demand Equilibrium"},"next":{"slug":"liquidity-adjusted-var","name":"Liquidity-Adjusted VaR"},"lesson":{"name":"Lesson 1 \xb7 Read a business through its numbers","to":"/courses/financial-data-to-insight/from-raw-numbers-to-decisions"},"total":522}')}}]);